"""Read the immutable data snapshot generated by Rust during native builds."""

import json
from pkgutil import get_data
from typing import List, TypedDict, cast


class BenchmarkData(TypedDict):
    id: int
    name: str


class ReferenceMachineData(TypedDict):
    name: str
    short_name: str
    os_name: str
    os_version: str
    cpu_architecture: str
    memory_bytes: int
    cpu_cores: int


class ReferenceResultData(TypedDict):
    benchmark: str
    score: float


class ReferenceRunData(TypedDict):
    started_at_unix_seconds: float
    start_temperature_c: float
    end_temperature_c: float
    warmup_seconds: float
    results: List[ReferenceResultData]


class Metadata(TypedDict):
    benchmarks: List[BenchmarkData]
    default_warmup_seconds: float
    default_measurement_seconds: float
    reference_machine: ReferenceMachineData
    reference_run: ReferenceRunData


_data = cast(bytes, get_data('benchset', '_metadata.json'))
DATA = cast(Metadata, json.loads(_data.decode('utf-8')))
_NAMES = {item['name']: item['name'] for item in DATA['benchmarks']}


def canonical_name(value: bytes) -> str:
    """Reuse public catalog strings when decoding native comparison operands."""
    name = value.decode('utf-8')
    return _NAMES.get(name, name)
